using System;
using System.Collections.Generic;
using System.Text;
using Server;
using Server.Items;
using Server.Misc;

namespace Server.Mobiles
{
    using Server.Custom.LLMNpc;

    // Base for any creature whose dialog is generated by the local LLM.
    // Subclasses set body/stats/outfit and a DefaultPersona; this class wires
    // speech in (HandlesOnSpeech + OnSpeech) and the async request/response loop.
    public abstract class LLMTalkingMobile : BaseCreature
    {
        private string m_Persona;
        private NpcIdentity m_Identity;
        private Dictionary<int, NpcRelationship> m_Relationships;

        public LLMTalkingMobile(AIType ai, FightMode mode, int rangePerception, int rangeFight, double activeSpeed, double passiveSpeed)
            : base(ai, mode, rangePerception, rangeFight, activeSpeed, passiveSpeed)
        {
        }

        public LLMTalkingMobile(Serial serial)
            : base(serial)
        {
        }

        // Persona override; if empty, DefaultPersona is used. Editable via [props.
        [CommandProperty(AccessLevel.GameMaster)]
        public string Persona
        {
            get { return m_Persona; }
            set { m_Persona = value; }
        }

        public abstract string DefaultPersona { get; }

        public virtual bool RespondsToPlayers { get { return true; } }

        // True for the wild, non-townsfolk speakers (orcs, liches, ogres, and the
        // like). Drives NPC-to-NPC chatter: monster speakers banter only with their
        // own kind and in a monster-aware frame, never amiably with townsfolk.
        public virtual bool IsMonsterSpeaker { get { return false; } }

        // A short scene description appended to the system prompt, e.g. mood/locale.
        public virtual string SceneHint { get { return ""; } }

        // Drives which flavor pool an identity is rolled from. Override per trade.
        public virtual string Vocation { get { return "townsperson"; } }

        // The generated, persisted identity. Lazily created the first time it is
        // needed (by which point the mobile has been placed in the world, so its
        // town can be resolved from its location).
        public NpcIdentity Identity
        {
            get
            {
                EnsureIdentity();
                return m_Identity;
            }
        }

        public void EnsureIdentity()
        {
            if (m_Identity != null && m_Identity.Assigned)
                return;

            string town = BritanniaGeography.TownOf(this);
            m_Identity = NpcIdentity.Generate(Vocation, town, this.Female);
        }

        public override bool HandlesOnSpeech(Mobile from)
        {
            if (LLMConfig.Enabled && RespondsToPlayers && from != null && from.Player && from.InRange(this.Location, LLMConfig.HearRange))
                return true;

            return base.HandlesOnSpeech(from);
        }

        public override void OnSpeech(SpeechEventArgs e)
        {
            base.OnSpeech(e);

            if (!LLMConfig.Enabled || !RespondsToPlayers || e == null)
                return;

            Mobile from = e.Mobile;

            if (from == null || from == this || !from.Player || from.Deleted)
                return;

            if (this.Map == null || this.Map == Map.Internal)
                return;

            string text = e.Speech;

            if (string.IsNullOrEmpty(text))
                return;

            text = text.Trim();

            if (text.Length == 0)
                return;

            if (!from.InRange(this.Location, LLMConfig.HearRange))
                return;

            if (!string.IsNullOrEmpty(LLMConfig.AllowedMap) &&
                (this.Map.Name == null || !this.Map.Name.Equals(LLMConfig.AllowedMap, StringComparison.OrdinalIgnoreCase)))
                return;

            Respond(from, text);
        }

        protected virtual string BuildSystemPrompt(Mobile player)
        {
            EnsureIdentity();

            string persona = string.IsNullOrEmpty(m_Persona) ? DefaultPersona : m_Persona;
            NpcIdentity id = m_Identity;

            StringBuilder sb = new StringBuilder();
            sb.Append("You are ");
            sb.Append(string.IsNullOrEmpty(this.Name) ? "an unnamed character" : this.Name);

            if (!string.IsNullOrEmpty(this.Title))
            {
                sb.Append(" ");
                sb.Append(this.Title);
            }

            sb.Append(", ");
            sb.Append(persona);
            sb.Append(". You live in the medieval fantasy realm of Britannia, the world of Ultima Online. ");

            if (id != null)
            {
                sb.Append("You hold your post in the town of ");
                sb.Append(id.Town);
                sb.Append(". ");

                if (!string.IsNullOrEmpty(id.Origin) && id.Origin != id.Town)
                {
                    sb.Append("You hail originally from ");
                    sb.Append(id.Origin);
                    sb.Append(". ");
                }

                if (!string.IsNullOrEmpty(id.Personality))
                {
                    sb.Append("Your temperament is ");
                    sb.Append(id.Personality);
                    sb.Append(". ");
                }

                if (!string.IsNullOrEmpty(id.Backstory))
                {
                    sb.Append(id.Backstory);
                    sb.Append(" ");
                }

                if (!string.IsNullOrEmpty(id.SpeechStyle))
                {
                    sb.Append("You speak in a manner that is ");
                    sb.Append(id.SpeechStyle);
                    sb.Append(". ");
                }

                if (!string.IsNullOrEmpty(id.Motivation))
                {
                    sb.Append("Privately — never say this outright — you are ");
                    sb.Append(id.Motivation);
                    sb.Append(". ");
                }

                if (!string.IsNullOrEmpty(id.Mood))
                {
                    sb.Append("Right now you are ");
                    sb.Append(id.Mood);
                    sb.Append(". ");
                }
            }

            sb.Append("Always stay in character. Reply with at most two short sentences in a medieval, in-world tone. ");
            sb.Append("Never break character, never mention being an AI or a computer, never mention the modern world or that this is a game. ");

            string scene = SceneHint;
            if (!string.IsNullOrEmpty(scene))
            {
                sb.Append(scene);
                sb.Append(" ");
            }

            sb.Append("You are speaking with an adventurer named ");
            sb.Append(string.IsNullOrEmpty(player.Name) ? "a stranger" : player.Name);
            sb.Append(". ");

            // What this NPC already remembers about this specific player. Reflects
            // state from before the current utterance (which is folded in afterward).
            NpcRelationship rel = GetRelationship(player);
            sb.Append(rel == null ? "You have never met them before." : rel.Recap());

            // P10/P11: townsfolk surface today's aim and the talk of the town;
            // wild speakers keep no civic gossip.
            if (!IsMonsterSpeaker)
            {
                string intent = DailyRoutine.IntentionOf(this.Serial.Value);
                if (!string.IsNullOrEmpty(intent))
                {
                    sb.Append(" Today you have a mind for ");
                    sb.Append(intent);
                    sb.Append(".");
                }

                sb.Append(TownGossip.PromptBlock(id != null && !string.IsNullOrEmpty(id.Town)
                    ? id.Town : BritanniaGeography.TownOf(this)));

                // P15: an open parcel-favor this NPC could offer the traveler.
                sb.Append(FavorDirector.PromptBlock(this.Serial.Value, player.Serial.Value));
            }

            // P7/P14: the (closed) action vocabulary — cosmetic gestures for
            // ordinary talkers, the keeper's powers for the Overseer (override).
            sb.Append(ActionInstruction());

            return sb.ToString();
        }

        // ---- action tags (P7 cosmetic; P14 overrides for the Overseer) --------

        protected virtual string ActionInstruction()
        {
            return NpcActions.PromptInstruction();
        }

        protected virtual string ExtractAction(string reply, out string verb)
        {
            return NpcActions.Extract(reply, FavorDirector.OfferVerbs, out verb);
        }

        protected virtual void PerformAction(Mobile player, string verb)
        {
            // A pending favor's [do:offer] takes precedence (P15); anything
            // else falls through to the cosmetic gestures.
            if (!FavorDirector.TryPerformOffer(this, player, verb))
                NpcActions.Perform(this, verb);
        }

        // P15: a delivered favor raises this NPC's regard for the courier —
        // even when the delivery happened a continent away.
        public void RecordFavor(Mobile player)
        {
            if (player == null)
                return;

            NpcRelationship rel = GetOrCreateRelationship(player);

            rel.Disposition += 15;
            if (rel.Disposition > 100)
                rel.Disposition = 100;
        }

        protected virtual void Respond(Mobile player, string text)
        {
            EnsureIdentity();

            int npcSerial = this.Serial.Value;
            int playerSerial = player.Serial.Value;

            // Build from prior state first, then fold this line into memory so the
            // prompt reflects history as it stood when the player started talking.
            List<LLMMessage> history = LLMConversation.Get(npcSerial, playerSerial);
            history.Add(new LLMMessage("user", text));

            string system = BuildSystemPrompt(player);

            NoteInteraction(player, text);

            // P11: a salient line told to a townsperson may enter the town's talk
            // (chance-gated inside). Monsters don't carry civic gossip.
            if (!IsMonsterSpeaker)
            {
                TownGossip.MaybeAddPlayerRumor(this, player, text);

                // P15: an eligible townsperson may roll a parcel-favor to offer
                // (gated inside; asking for work guarantees it).
                FavorDirector.MaybeCreatePending(this, player, text);
            }

            string key = npcSerial.ToString();
            string archetype = (m_Identity != null) ? m_Identity.Archetype : "";
            string region = (m_Identity != null) ? m_Identity.Town : "";

            LLMTalkingMobile mob = this;

            Mobile talker = player;

            LLMClient.TryDispatch(key, system, history, text, region, archetype, npcSerial, delegate(bool ok, string reply)
            {
                if (mob == null || mob.Deleted)
                    return;

                if (!ok || string.IsNullOrEmpty(reply))
                    return;

                // Strip an action tag before speaking/recording; run the action
                // after the words so the gesture (or the Overseer's power) lands
                // on what was just said.
                string verb;
                string spoken = mob.ExtractAction(reply, out verb);

                LLMConversation.Record(npcSerial, playerSerial, "user", text);
                LLMConversation.Record(npcSerial, playerSerial, "assistant", spoken);

                if (spoken.Length > 0)
                    mob.SpeakReply(spoken);

                mob.PerformAction(talker, verb);
            });
        }

        // ---- persistent relationship tracking -------------------------------

        private void EnsureRelationships()
        {
            if (m_Relationships == null)
                m_Relationships = new Dictionary<int, NpcRelationship>();
        }

        private NpcRelationship GetRelationship(Mobile player)
        {
            if (player == null)
                return null;

            EnsureRelationships();

            NpcRelationship rel;
            if (m_Relationships.TryGetValue(player.Serial.Value, out rel))
                return rel;

            return null;
        }

        private NpcRelationship GetOrCreateRelationship(Mobile player)
        {
            EnsureRelationships();

            int ps = player.Serial.Value;

            NpcRelationship rel;
            if (!m_Relationships.TryGetValue(ps, out rel))
            {
                rel = new NpcRelationship();
                m_Relationships[ps] = rel;
            }

            return rel;
        }

        private void NoteInteraction(Mobile player, string text)
        {
            if (player == null)
                return;

            NpcRelationship rel = GetOrCreateRelationship(player);
            rel.Note(text);

            if (m_Identity != null)
                m_Identity.DriftMood();
        }

        // GM-facing summary of who this NPC remembers, one line per player.
        public List<string> MemoryLines()
        {
            List<string> lines = new List<string>();

            if (m_Relationships == null || m_Relationships.Count == 0)
            {
                lines.Add("(no one remembered yet)");
                return lines;
            }

            foreach (KeyValuePair<int, NpcRelationship> kv in m_Relationships)
            {
                NpcRelationship rel = kv.Value;
                Mobile pl = World.FindMobile((Serial)kv.Key);
                string who = (pl != null && !string.IsNullOrEmpty(pl.Name)) ? pl.Name : ("#" + kv.Key);

                string topics = rel.TopicSummary();
                string line = who + ": " + rel.Conversations + " talk(s), " + rel.Lines +
                    " line(s), disposition " + rel.Disposition;

                if (topics.Length > 0)
                    line += " — recalls " + topics;

                lines.Add(line);
            }

            return lines;
        }

        protected virtual void SpeakReply(string reply)
        {
            this.Say(reply);
        }

        public override void OnDelete()
        {
            base.OnDelete();
            LLMConversation.ClearNpc(this.Serial.Value);
        }

        public override void Serialize(GenericWriter writer)
        {
            base.Serialize(writer);

            writer.Write((int)2); // version
            writer.Write(m_Persona);

            // identity
            bool hasId = m_Identity != null;
            writer.Write(hasId);
            if (hasId)
                m_Identity.Serialize(writer);

            // relationships
            int n = m_Relationships == null ? 0 : m_Relationships.Count;
            writer.Write(n);

            if (m_Relationships != null)
            {
                foreach (KeyValuePair<int, NpcRelationship> kv in m_Relationships)
                {
                    writer.Write(kv.Key);
                    kv.Value.Serialize(writer);
                }
            }
        }

        public override void Deserialize(GenericReader reader)
        {
            base.Deserialize(reader);

            int version = reader.ReadInt();

            if (version >= 1)
                m_Persona = reader.ReadString();

            m_Relationships = new Dictionary<int, NpcRelationship>();

            if (version >= 2)
            {
                bool hasId = reader.ReadBool();
                if (hasId)
                {
                    m_Identity = new NpcIdentity();
                    m_Identity.Deserialize(reader);
                }

                int n = reader.ReadInt();
                for (int i = 0; i < n; i++)
                {
                    int ps = reader.ReadInt();
                    NpcRelationship rel = new NpcRelationship();
                    rel.Deserialize(reader);
                    m_Relationships[ps] = rel;
                }
            }
        }
    }

    // ----- Concrete personas -------------------------------------------------

    // A passive human townsperson.
    public class LLMVillager : LLMTalkingMobile
    {
        [Constructable]
        public LLMVillager()
            : base(AIType.AI_Animal, FightMode.None, 10, 1, 0.2, 0.4)
        {
            SpeechHue = 0x3B2;
            InitHuman();
            InitStats(60, 60, 25);

            if (Female)
                AddItem(new PlainDress(Utility.RandomNeutralHue()));
            else
                AddItem(new Shirt(Utility.RandomNeutralHue()));

            AddItem(new ShortPants(Utility.RandomNeutralHue()));
            AddItem(new Shoes(Utility.RandomNeutralHue()));

            Utility.AssignRandomHair(this);
        }

        public LLMVillager(Serial serial)
            : base(serial)
        {
        }

        public override string DefaultPersona
        {
            get { return "a humble villager who tends fields and knows the local gossip"; }
        }

        public override string Vocation { get { return "villager"; } }

        public override string SceneHint
        {
            get { return "You go about your daily work among the cottages and fields."; }
        }

        protected void InitHuman()
        {
            Female = Utility.RandomBool();
            Body = Female ? 0x191 : 0x190;
            Name = NameList.RandomName(Female ? "female" : "male");
        }

        public override void Serialize(GenericWriter writer)
        {
            base.Serialize(writer);
            writer.Write((int)0);
        }

        public override void Deserialize(GenericReader reader)
        {
            base.Deserialize(reader);
            int version = reader.ReadInt();
        }
    }

