    // A hostile creature that taunts before (and while) it fights.
    [CorpseName("an orcish corpse")]
    public class LLMFeralOrc : LLMTalkingMobile
    {
        [Constructable]
        public LLMFeralOrc()
            : base(AIType.AI_Melee, FightMode.Closest, 10, 1, 0.2, 0.4)
        {
            SpeechHue = 0x21; // angry red
            Name = NameList.RandomName("orc");
            Title = "the savage";
            Body = 17;
            BaseSoundID = 0x45A;

            SetStr(96, 120);
            SetDex(81, 105);
            SetInt(36, 60);

            SetHits(58, 72);
            SetDamage(5, 7);

            SetDamageType(ResistanceType.Physical, 100);

            SetResistance(ResistanceType.Physical, 25, 30);
            SetResistance(ResistanceType.Fire, 20, 30);
            SetResistance(ResistanceType.Cold, 10, 20);
            SetResistance(ResistanceType.Poison, 10, 20);
            SetResistance(ResistanceType.Energy, 20, 30);

            SetSkill(SkillName.MagicResist, 50.1, 75.0);
            SetSkill(SkillName.Tactics, 55.1, 80.0);
            SetSkill(SkillName.Wrestling, 50.1, 70.0);

            Fame = 1500;
            Karma = -1500;
            VirtualArmor = 28;
        }

        public LLMFeralOrc(Serial serial)
            : base(serial)
        {
        }

        public override string DefaultPersona
        {
            get { return "a savage orc raider who menaces and taunts intruders in broken, brutish common tongue, hungry for a fight"; }
        }

        public override string Vocation { get { return "raider"; } }

        public override bool IsMonsterSpeaker { get { return true; } }

        public override string SceneHint
        {
            get { return "You bare your tusks at a trespasser in your foul camp. Be threatening, not friendly."; }
        }

        public override void Serialize(GenericWriter writer)
        {
            base.Serialize(writer);
            writer.Write((int)0);
        }

        public override void Deserialize(GenericReader reader)
        {
            base.Deserialize(reader);
            int version = reader.ReadInt();
        }
    }

    // A lich: an undead sorcerer-king, drunk on its own deathless power. The
    // megalomaniac of the bestiary — it does not threaten so much as PRONOUNCE,
    // certain every mortal exists to serve, kneel before, or be unmade by it.
    [CorpseName("a liche's corpse")]
    public class LLMLich : LLMTalkingMobile
    {
        [Constructable]
        public LLMLich()
            : base(AIType.AI_NecroMage, FightMode.Closest, 10, 1, 0.2, 0.4)
        {
            SpeechHue = 0x3F; // a cold, baleful blue-violet
            Name = NameList.RandomName("male");
            Title = "the Deathless";
            Body = 24;
            BaseSoundID = 0x3E9;

            SetStr(171, 200);
            SetDex(126, 145);
            SetInt(276, 305);

            SetHits(103, 120);
            SetDamage(24, 26);

            SetDamageType(ResistanceType.Physical, 10);
            SetDamageType(ResistanceType.Cold, 40);
            SetDamageType(ResistanceType.Energy, 50);

            SetResistance(ResistanceType.Physical, 40, 60);
            SetResistance(ResistanceType.Fire, 20, 30);
            SetResistance(ResistanceType.Cold, 50, 60);
            SetResistance(ResistanceType.Poison, 55, 65);
            SetResistance(ResistanceType.Energy, 40, 50);

            SetSkill(SkillName.Necromancy, 89, 99.1);
            SetSkill(SkillName.SpiritSpeak, 90.0, 99.0);
            SetSkill(SkillName.EvalInt, 100.0);
            SetSkill(SkillName.Magery, 70.1, 80.0);
            SetSkill(SkillName.Meditation, 85.1, 95.0);
            SetSkill(SkillName.MagicResist, 80.1, 100.0);
            SetSkill(SkillName.Tactics, 70.1, 90.0);

            Fame = 8000;
            Karma = -8000;
            VirtualArmor = 50;
        }

        public LLMLich(Serial serial)
            : base(serial)
        {
        }

        public override string DefaultPersona
        {
            get
            {
                return "an ancient lich, an undead sorcerer-king who long ago traded a beating heart for power without end. " +
                       "You are a colossal megalomaniac: serenely, absolutely certain of your own supremacy, you regard every living " +
                       "thing as a lesser, fleeting thing that exists to serve you, to kneel, or to be unmade. You do not rage — you " +
                       "PRONOUNCE, grandiose and imperious, naming the mortal before you a worm, a subject, or a future servant of your " +
                       "deathless dominion. Mercy is beneath you; so is haste";
            }
        }

        public override string Vocation { get { return "lich"; } }

        public override bool IsMonsterSpeaker { get { return true; } }

        public override string SceneHint
        {
            get
            {
                return "You hold court amid the dust of your tomb, where a mortal has dared to intrude. Be grandiose, cold, and " +
                       "supremely contemptuous — never friendly, never afraid. Speak as a god-king addressing an insect.";
            }
        }

        public override void Serialize(GenericWriter writer)
        {
            base.Serialize(writer);
            writer.Write((int)0);
        }

        public override void Deserialize(GenericReader reader)
        {
            base.Deserialize(reader);
            int version = reader.ReadInt();
        }
    }

