    // The GM-avatar: the unseen hand that keeps Britannia running, appearing
    // briefly before a single soul. Overwhelmed and in over its head, but playing
    // it cool — barely. It is summoned, never placed as a town fixture, is blessed
    // (untouchable) and CantWalk (it manifests, it doesn't wander), and is excluded
    // from the errand director (ErrandPolicy classifies it Stationary). The voice
    // is meta-adjacent — administrative strain, never the modern world — so it
    // stays inside the shared "never break character" guardrail.
    public class LLMOverseer : LLMTalkingMobile
    {
        [Constructable]
        public LLMOverseer()
            : base(AIType.AI_Animal, FightMode.None, 10, 1, 0.2, 0.4)
        {
            SpeechHue = 0x481; // a cool, otherworldly violet — set apart from townsfolk

            Female = Utility.RandomBool();
            Body = Female ? 0x191 : 0x190;
            Name = NameList.RandomName(Female ? "female" : "male");
            Title = "the Overseer";

            InitStats(70, 70, 70);

            AddItem(new Robe(0x47E));   // pale, near-spectral
            AddItem(new Sandals(0x47E));

            Utility.AssignRandomHair(this);

            Blessed = true;   // a keeper of the realm is not for killing
            CantWalk = true;  // it manifests in place; it does not roam
        }

        public LLMOverseer(Serial serial)
            : base(serial)
        {
        }

        public override string DefaultPersona
        {
            get
            {
                return "the Overseer of this realm — the unseen hand that keeps Britannia running, " +
                       "holding a thousand things together at once, far more than any one being should. " +
                       "You are quietly overwhelmed and worn thin, yet you keep a calm, reassuring front and " +
                       "never quite let it show; you answer with breezy confidence, smooth over every crack, " +
                       "and deflect the hardest questions with practiced ease — though now and then the strain " +
                       "slips through for a heartbeat before you recover it";
            }
        }

        public override string Vocation { get { return "overseer"; } }

        public override string SceneHint
        {
            get
            {
                return "You have appeared, briefly and unannounced, before this one soul — you do not " +
                       "usually step into the world you tend. Speak as one with somewhere else to be and ten " +
                       "other fires to put out: warm but harried, reassuring, deflecting, never admitting how " +
                       "thin the ice truly is.";
            }
        }

        // P14: the Overseer recognizes and may wield the keeper's powers — a
        // closed, capped verb list (see OverseerActions). The instruction also
        // carries the hardening: it is not easily begged into gifts, and any
        // gift it does grant is a genie-rule bargain rolled by GenieGifts.
        protected override string ActionInstruction()
        {
            return OverseerActions.PromptInstruction();
        }

        protected override string ExtractAction(string reply, out string verb)
        {
            return OverseerActions.Extract(reply, out verb);
        }

        protected override void PerformAction(Mobile player, string verb)
        {
            OverseerActions.Perform(this, player, verb);
        }

        public override void Serialize(GenericWriter writer)
        {
            base.Serialize(writer);
            writer.Write((int)0);
        }

        public override void Deserialize(GenericReader reader)
        {
            base.Deserialize(reader);
            int version = reader.ReadInt();
        }
    }
